// The first element's address as a number, so that comparing it after a change is well defined.
template <typename Container>
[[nodiscard]] std::uintptr_t first_address(const Container& c) {
  return reinterpret_cast<std::uintptr_t>(std::addressof(*c.begin()));
}

template <typename Container>
void append_999(std::string_view name) {
  Container c{0};
  std::int64_t moved = 0;
  for (int i = 1; i < 1000; ++i) {
    const std::uintptr_t before = first_address(c);
    c.push_back(i);
    if (first_address(c) != before) ++moved;
  }
  std::cout << std::format("{:<14} first element moved {:>2} times\n", name, moved);
}

int main() {
  append_999<std::vector<int>>("vector");
  append_999<std::deque<int>>("deque");
  append_999<std::list<int>>("list");

  std::unordered_map<int, int> ids{{0, 0}};
  const auto before = reinterpret_cast<std::uintptr_t>(&ids.at(0));
  std::int64_t rehashes = 0;
  for (int i = 1; i < 1000; ++i) {
    const auto buckets = ids.bucket_count();
    ids.emplace(i, i);
    if (ids.bucket_count() != buckets) ++rehashes;
  }
  const bool moved = reinterpret_cast<std::uintptr_t>(&ids.at(0)) != before;
  std::cout << std::format("unordered_map  {} rehashes, element 0 moved: {}\n", rehashes, moved);
}

#include <deque>
#include <format>
#include <iostream>

int main() {
  std::deque<int> readings{7, 8, 9};
  const int& oldest = readings.front();  // a reference: survives pushes at either end
  auto next = readings.begin();          // an iterator: any push at either end invalidates it
  for (int i = 0; i < 2000; ++i) readings.push_back(i);
  int sum = oldest;                                     // fine
  for (; next != readings.end(); ++next) sum += *next;  // walks with a dead iterator
  std::cout << std::format("sum {}\n", sum);
}

