int main() {
  std::string short_name = "lidar";                        // 5 characters: in the buffer inside the object
  std::string long_name = "lidar/front/points_filtered";  // 27 characters: on the heap
  const std::string_view short_view = short_name;
  const std::string_view long_view = long_name;
  const std::string short_owner = std::move(short_name);
  const std::string long_owner = std::move(long_name);
  std::cout << std::format("short view still reads \"lidar\": {}\n", short_view == "lidar");
  std::cout << std::format("long view still reads the path:  {}\n", long_view == "lidar/front/points_filtered");
}

