#include <algorithm>
#include <concepts>
#include <iostream>
#include <ranges>
#include <string>
#include <string_view>

int main() {
  const std::string line = "scan 42 ok";
  // Even from a temporary view, find returns an iterator into line, not a dangling.
  static_assert(!std::same_as<decltype(std::ranges::find(std::string_view(line), ' ')), std::ranges::dangling>);

  const std::string_view view(line);
  const auto space = std::ranges::find(view, ' ');
  if (space == view.end()) {
    std::cout << "no space in the line\n";
    return 0;
  }
  std::cout << std::string_view(space + 1, view.end()) << '\n';
}

