class Robot {
 public:
  explicit Robot(std::string name) : name_(std::move(name)) {}
  [[nodiscard]] std::string_view name() const { return name_; }
  [[nodiscard]] std::span<const double> gains() const { return gains_; }
  void rename(std::string name) { name_ = std::move(name); }
  void add_gain(double gain) { gains_.push_back(gain); }

 private:
  std::string name_;
  std::vector<double> gains_;
};

int main() {
  Robot robot("turtlebot3-burger-lab-2");
  robot.add_gain(0.8);
  const std::string_view name = robot.name();
  const std::span<const double> gains = robot.gains();
  robot.add_gain(1.2);
  robot.rename("turtlebot3-waffle-lab-2");
  std::cout << std::format("{} has {} gains, the first {}\n", name, gains.size(), gains[0]);
}

#include <format>
#include <iostream>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

class Robot {
 public:
  explicit Robot(std::string name) : name_(std::move(name)) {}
  // Both views are valid until the next call of a non-const member function on this robot.
  [[nodiscard]] std::string_view name() const { return name_; }
  [[nodiscard]] std::span<const double> gains() const { return gains_; }
  void rename(std::string name) { name_ = std::move(name); }
  void add_gain(double gain) { gains_.push_back(gain); }

 private:
  std::string name_;
  std::vector<double> gains_;
};

int main() {
  Robot robot("turtlebot3-burger-lab-2");
  robot.add_gain(0.8);
  // Kept across changes to the robot, so copied into owners.
  const std::string old_name(robot.name());
  const std::vector<double> old_gains(robot.gains().begin(), robot.gains().end());
  robot.add_gain(1.2);
  robot.rename("turtlebot3-waffle-lab-2");
  std::cout << std::format("was {} with {} gain, the first {}\n", old_name, old_gains.size(), old_gains[0]);
  // Used at once, before anything changes the robot, so a view is enough.
  const std::span<const double> gains = robot.gains();
  std::cout << std::format("now {} with {} gains, the first {}\n", robot.name(), gains.size(), gains[0]);
}

#include <cstdint>
