#include <iostream>
#include <string>
#include <unordered_map>

struct Track {
  std::int64_t last_seen_ms;
};

int main() {
  std::unordered_map<std::string, Track> tracks{
      {"cone-1", {.last_seen_ms = 100}}, {"cone-2", {.last_seen_ms = 950}},
      {"person-7", {.last_seen_ms = 400}}, {"pallet-3", {.last_seen_ms = 990}}};
  const std::int64_t now_ms = 1000;
  for (auto it = tracks.begin(); it != tracks.end(); ++it) {
    if (now_ms - it->second.last_seen_ms > 500) tracks.erase(it);  // it dies here, and ++it reads it
  }
  std::cout << std::format("{} tracks left\n", tracks.size());
}

