};

int main() {
  std::unordered_map<std::string, Track> tracks{
      {"cone-1", {.last_seen_ms = 100}}, {"cone-2", {.last_seen_ms = 950}},
      {"person-7", {.last_seen_ms = 400}}, {"pallet-3", {.last_seen_ms = 990}}};
  const std::int64_t now_ms = 1000;
  const auto stale = [now_ms](const auto& entry) { return now_ms - entry.second.last_seen_ms > 500; };
  const auto dropped = std::erase_if(tracks, stale);  // C++20: the loop, written once and correctly
  std::cout << std::format("dropped {}, {} tracks left\n", dropped, tracks.size());
}

