int main() {
  std::vector<int> ranges_mm{820, 0, 0, 1540, 0};  // 0 means the beam saw nothing
  for (auto it = ranges_mm.begin(); it != ranges_mm.end(); ++it) {
    if (*it == 0) ranges_mm.erase(it);  // shifts the rest left, then ++it skips one
  }
  std::cout << std::format("{} readings left\n", ranges_mm.size());
}

