struct Waypoint {
  std::string name;
  double x_m = 0;
  double y_m = 0;
};

int main() {
  std::vector<Waypoint> route{{.name = "dock"}, {.name = "shelf-4", .x_m = 12, .y_m = 3}};
  const Waypoint& goal = route.back();
  route.push_back({.name = "detour", .x_m = 6, .y_m = -2});  // full: reallocates, and goal dangles
  std::cout << std::format("heading for {} at ({}, {})\n", goal.name, goal.x_m, goal.y_m);
}

#include <cstddef>
#include <format>
#include <iostream>
#include <iterator>
#include <string>
#include <vector>

struct Waypoint {
  std::string name;
  double x_m = 0;
  double y_m = 0;
};

int main() {
  // Fix 1: hold an index. It names a position, and positions survive reallocation.
  std::vector<Waypoint> route{{.name = "dock"}, {.name = "shelf-4", .x_m = 12, .y_m = 3}};
  const std::ptrdiff_t goal = std::ssize(route) - 1;
  route.push_back({.name = "detour", .x_m = 6, .y_m = -2});
  std::cout << std::format("index:   heading for {} at ({}, {})\n", route[goal].name, route[goal].x_m, route[goal].y_m);

  // Fix 2: reserve first. The reference is safe only while the pushes stay within the capacity.
  std::vector<Waypoint> planned{{.name = "dock"}, {.name = "shelf-4", .x_m = 12, .y_m = 3}};
  planned.reserve(planned.size() + 1);
  const Waypoint& target = planned.back();
  planned.push_back({.name = "detour", .x_m = 6, .y_m = -2});
  std::cout << std::format("reserve: heading for {} at ({}, {})\n", target.name, target.x_m, target.y_m);
}

