#include <vector>

struct Waypoint {
  std::string name;
  bool blocked = false;
};

int main() {
  std::vector<Waypoint> route{{.name = "dock"}, {.name = "door", .blocked = true}, {.name = "shelf-4"}};
  for (const Waypoint& w : route) {
    if (w.blocked) route.push_back({.name = w.name + "-detour"});  // the loop's hidden iterators die here
  }
  std::cout << std::format("{} waypoints\n", route.size());
}

#include <cstddef>
#include <format>
#include <iostream>
#include <iterator>
#include <string>
#include <vector>

struct Waypoint {
  std::string name;
  bool blocked = false;
};

int main() {
  std::vector<Waypoint> route{{.name = "dock"}, {.name = "door", .blocked = true}, {.name = "shelf-4"}};
  const std::ptrdiff_t planned = std::ssize(route);  // visit the original waypoints only
  for (std::ptrdiff_t i = 0; i < planned; ++i) {
    if (route[i].blocked) route.push_back({.name = route[i].name + "-detour"});
  }
  for (const Waypoint& w : route) std::cout << w.name << ' ';
  std::cout << '\n';
}
